int countDistinctCharacters(String string) {
  if (string.isEmpty) return 0;

  final Set<String> uniqueChars = Set();

  for (var i = 0; i < string.length; i++) {
    var char = string[i];

    // Check if the character is a letter and not a diacritic
    bool isLetterWithoutDiacritics = char.runes.any((runes) => runes == char.codeUnitAt(0));

    if (!isLetterWithoutDiacritics && !char.isLetter) continue;

    int codePoint = char.codeUnits.first;
    String normalizedChar = String.fromCharCode(codePoint);

    if (normalizedChar != char) {
      // If normalization changed, check again with the normalized version
      codePoint = normalizedChar.codeUnits.first;
      normalizedChar = String.fromCharCode(codePoint);

      if (normalizedChar != char) continue;
    }

    uniqueChars.add(normalizedChar);
  }

  return uniqueChars.length;
}
