  int noteLength = 0;

  for (int i = 0; i < musicString.length; ++i) {
    final char = musicString[i];

    if (char == '[') {
      // Start of a new note
      if (currentNote != -1) {
        // End the previous note
        result.add(currentNote);
        currentNote = -1;
      }
      noteLength = 0;
    } else if (char == ']') {
      // End of a note, add to list
      if (noteLength > 0 && currentNote != -1) {
        result.add(currentNote);
      }
      currentNote = -1;
    } else if (char == '-') {
      // Add '-' as part of the note length
      noteLength *= 10;
      noteLength += int.parse(char); 
    } else if ('A' <= char && char <= 'G') {
      // Note value is given by the letter and duration
      final noteValue = _getNoteValue(char);
      currentNote = noteValue;
      noteLength = 0;
    } else if (char == '_') {
      // Underscore indicates an extra beat or tie?
      // Assuming it's just adding one more beat
      if (currentNote != -1) {
        currentNote++;
      }
    }
  }

  return result;
