  final List<int> notes = [];

  int i = 0;
  while (i < musicString.length) {
    if (musicString[i] == ' ') {
      ++i;
      continue;
    }

    // Check for note duration
    bool isLongNote = false;
    if (i + 1 < musicString.length && musicString[i+1] == '_') {
      isLongNote = true;
      ++i; // Skip the underscore
    }

    // Parse pitch class and octave
    String pitchClass = '';
    int octave = -1;
    int j = i;
    while (j < musicString.length && 
           (musicString[j].toUpperCase() >= 'A' && musicString[j].toUpperCase() <= 'G')) {
      pitchClass += musicString[j];
      ++j;
    }

    if (pitchClass.isEmpty) {
      throw FormatException('Invalid note: ${musicString.substring(i)}');
    }

    // Determine base frequency based on pitch class
    int baseFrequencyIndex;
    switch (pitchClass.toLowerCase()) {
      case 'a': baseFrequencyIndex = 4; break;
      case 'b': baseFrequencyIndex = 3; break;
      case 'c': baseFrequencyIndex = 2; break;
      case 'd': baseFrequencyIndex = 1; break;
      case 'e': baseFrequencyIndex = 0; break;
      case 'f': baseFrequencyIndex = 7; break;
      case 'g': baseFrequencyIndex = 6; break;
      default:
        throw FormatException("Unknown pitch class: $pitchClass");
    }

    // Process accidental modifiers
    int accidentalModifier = 0;
    int k = j;
    while (k < musicString.length) {
      char c = musicString[k];
      if (c == '#') {
        accidentalModifier++;
        ++k;
      } else if (c == 'b') {
        accidentalModifier--;
        ++k;
      } else {
        break;
      }
    }

    // Calculate effective index with accidentals
    baseFrequencyIndex += accidentalModifier;

    // Handle octaves
    int octaveNum = 4; // Default to C4 as middle C

    // Check for octave modifier
    if (k < musicString.length && musicString[k].isDigit()) {
      octaveNum = int.parse(musicString[k]);
      ++k;
    }

    // Convert to MIDI note number
    int midiNote = 12 * (octaveNum + 9) + baseFrequencyIndex;

    // Adjust for sharps/flats via accidentals
    if (accidentalModifier > 0) {
      midiNote += accidentalModifier % 12;
    } else if (accidentalModifier < 0) {
      midiNote -= (-accidentalModifier) % 12;
    }

    // Ensure valid range of notes (C2 to B8)
    if (midiNote < 24 || midiNote > 108) {
      throw FormatException("Note out of range: $midiNote");
    }

    // Set duration based on long note marker
    int duration = isLongNote ? 5 : 1;

    // Add note value to list
    notes.add(midiNote);

    // Advance pointer
    i = k;
  }

  return notes;
}

