    } else if (c == '-') {
      // Rest, add a zero to indicate rest
      return [0];
    } else {
      throw Exception('Unknown character in music string: $c');
    }
  }

  // Add the last note with its duration
  return [...[duration], ...{for(int j=0;j<duration;j++){(currentNoteIndex)} }];
