import 'dart:math';

bool correctBracketing(String brackets) {
  if (brackets.isEmpty) return true;

  // Check if the length is even, since each bracket must have a pair.
  if (brackets.length % 2 != 0) return false;

  Map<String, String> openingToClosing = {
    '(': ')',
    '{': '}',
    '[': ']'
  };

  List<String> stack = [];

  for (var i = 0; i < brackets.length; i++) {
    var currentChar = brackets[i];

    if (openingToClosing.containsKey(currentChar)) {
      stack.add(currentChar);
    } else {
      // If it's a closing bracket, check if the top of the stack matches
      if (stack.isEmpty) return false;
      var lastOpening = stack.removeLast();
      if (openingToClosing[lastOpening] != currentChar) return false;
    }
  }

  return stack.isEmpty;
}

