bool willItFly(List<int> q, int w) {
  if (q.length == 0 || q.length > 16) return false;

  final total = q.fold(0, (sum, val) => sum + val);
  if (total != w) return false;

  bool isPossible(int start, int end, List<int> nums, int targetSum, int currentSum, Set<List<int>> seen) {
    if (currentSum > targetSum) return false;

    for (int i = start; i < end && i <= nums.length - 1; i++) {
      var newSum = currentSum + nums[i];
      if (newSum > targetSum) break;

      if (!seen.contains([i])) {
        // Check if we have already used this index in a different order or same group of elements with the same sum.
        if (newSum == targetSum) {
          return true;
        }

        seen.add([i]);
        if (isPossible(i + 1, end, nums, targetSum, newSum, seen)) {
          return true;
        }
        seen.removeLast();
      }
    }

    return false;
  }

  final subsetSize = q.length ~/ 2;
  final indicesList = List.generate(q.length, (index) => index).toList();

  for (var i = subsetSize; i >= 1; i--) {
    final combinations = generateCombinations(indicesList, i);

    for (final combo in combinations) {
      final selectedValues = combo.map((idx) => q[idx]).toList();
      final subTotal = selectedValues.reduce((a, b) => a + b);
      if (subTotal == w / 2) {
        final remainingIndices = indicesList.whereNotIn(combo).toList();
        final remainingValues = remainingIndices.map((idx) => q[idx]).toList();
