String encrypt(String s) {
  final _key = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  final _chars = List<String>.generate(256, (i) => String.fromCharCode(i));

  int l = _key.length;
  for (int i=0; i < _chars.length; i++) {
    if (_chars[i] == '\r') continue;
    var pos = -1;
    for (var j=0; j < l && pos == -1; j++) {
      if (_chars[i] == _key[j]) {
        pos = j;
      }
    }
    if (pos != -1) {
      _chars[i] = _key[pos];
    } else {
      _chars[i] = _chars[i].toLowerCase();
    }
  }

  int c = 0;
  var out = '';
  for (var ch in s.split('')) {
    if (ch.isEmpty) continue;

    if (c >= _chars.length) c = 0;

    bool found = false;
    for (var k=0; k < _chars.length && !found; k++) {
      if (_chars[k] == ch) {
        found = true;
        break;
      }
    }

    if (!found) {
      out += ch;
      c++;
      continue;
    }

    out += _chars[(k + c) % _chars.length];
    c++;
  }

  return out;
}
