String getPrimaryCasing(String s) {
  if (s == null) return '';

  var lower = s.toLowerCase();
  var upper = s.toUpperCase();

  // Snake case has underscores
  if (lower.contains('_')) return 'snake';

  // Camel case starts with lowercase but contains at least one uppercase later
  if (lower.startsWith(lower[0]) && 
      s.length > 1 &&
      s.substring(1).contains(upper[1])) {
    return 'camel';
  }

  // Pascal case starts with uppercase
  if (s[0].toUpperCase() == s[0] && 
      s.length > 1 &&
      s.substring(1).contains(upper[1])) {
    return 'pascal';
  }

  return 'unknown';
}

