int maxFill(List<List<int>> grid, int capacity) {
  if (grid == null || grid.isEmpty || capacity < 0) return 0;

  final rows = grid.length;
  final cols = grid[0].length;

  // Initialize a matrix to keep track of the maximum amount filled
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));

  // Fill bottom-right cell first with minimum between its own value and capacity
  dp[rows - 1][cols - 1] = min(grid[rows - 1][cols - 1], capacity);

  // Iterate from right to left and top to bottom for filling each cell
  for (var r in 0...rows-1) {
    for (var c in 0...cols-1) {
      if (r == rows-1 && c == cols-1) continue; // Skip last cell already processed

      var currVal = grid[r][c];

      // If it's the last row or column, fill only horizontally or vertically respectively
      if (r == rows-1) {
        dp[r][c] = min(currVal + dp[r][c+1], capacity);
      } else if (c == cols-1) {
        dp[r][c] = min(currVal + dp[r+1][c], capacity);
      } else {
        // Else take the sum of current value plus minimum of both adjacent cells
        dp[r][c] = min(currVal + min(dp[r+1][c], dp[r][c+1]), capacity);
      }
    }
  }

  // The result is the total filled at [0][0]
  return dp[0][0];
}

