    return 0;
  } else if (grid[row][col] > 0) {
    total += grid[row][col];
  }

  total += dfs(grid, visited, row + 1, col, rows, cols, capacity);
  total += dfs(grid, visited, row - 1, col, rows, cols, capacity);
  total += dfs(grid, visited, row, col + 1, rows, cols, capacity);
  total += dfs(grid, visited, row, col - 1, rows, cols, capacity);

