// Helper function to find the previous greater or equal element in a list
int? _findPreviousGreaterOrEqualElement(List<int> arr, int start) {
  for (int i = start; i >= 0; i--) {
    if (arr[i] >= arr[start]) {
      return i;
    }
  }
  return null;
}

List<int> maximum(List<int> arr, int k) {
  if (arr.isEmpty || k <= 0) return [];

  final n = arr.length;
  if (k > n) return [];

  // Initialize the answer with the first window's max value
  List<int> result = [arr[0]];
  int currentWindowStartIndex = 0;

  while (currentWindowStartIndex < n - k) {
    // Find next greater element of the current window's max
    int? nextGreaterIndex = _findNextGreaterElement(arr, currentWindowStartIndex);

    if (nextGreaterIndex == null) {
      // No larger elements found, move window one step ahead
      currentWindowStartIndex++;
      continue;
    }

    // Find the position where we need to insert this new max
    int insertionPosition = nextGreaterIndex;

    // Slide the window by moving all elements from the original starting point up to the insertion position forward by one
    for (int i = currentWindowStartIndex; i < insertionPosition; i++) {
      arr[i] = arr[i + 1];
    }

    // Update the array at insertionPosition with the new max
    arr[insertionPosition] = arr[currentWindowStartIndex];

    // Move the window start to the insertion position + 1
    currentWindowStartIndex = insertionPosition + 1;

    // Add the new max to the result
    result.add(arr[insertionPosition]);
  }

  return result;
}
