List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  if (rows == 0) return [];
  final cols = grid[0].length;

  // Directions: up, right, down, left
  const directions = <int>[ -1, 0, 1, 0 ];

  // Min-heap to track the minimum path sums with current position and sum so far
  final pq = PriorityQueue<MinHeapNode>();

  for (var i = 0; i < rows; ++i) {
    var currSum = 0;
    for (var j = 0; j < cols; ++j) {
      currSum += grid[i][j];
      pq.add(MinHeapNode(i, j, currSum));
    }
  }

  while (!pq.isEmpty()) {
    final node = pq.remove();

    if (node.sum >= k) continue;

    final row = node.row;
    final col = node.col;
    final currSum = node.sum;

    if (row == rows - 1 && col == cols - 1) {
      return [currSum + grid[row][col]];
    }

    for (var d in directions) {
      var nextRow = row + d;
      var nextCol = col + d;

