bool simplify(String x, String n) {
  // Check if both strings are non-empty
  if (x.isEmpty || n.isEmpty) return false;

  final List<String> xList = x.split(' ');
  final List<String> nList = n.split(' ');

  // Ensure the number of elements in each list is equal
  if (xList.length != nList.length) return false;

  bool allPositive = true;
  for (var i = 0; i < xList.length; ++i) {
    var xStr = xList[i];
    var nStr = nList[i];

    // Validate that both are valid integers or floating points
    try {
      double xVal = double.tryParse(xStr);
      double nVal = double.tryParse(nStr);

      if (xVal == null || nVal == null) return false;

      // Check if both numbers are positive
      if (xVal <= 0 || nVal <= 0) {
        allPositive = false;
      }
    } catch (_) {
      return false;
    }
  }

  // If any element is zero and its corresponding value is also zero, it's invalid
  for (int i = 0; i < xList.length; ++i) {
    double xVal = double.parse(xList[i]);
    double nVal = double.parse(nList[i]);

    if (xVal == 0 && nVal == 0) return false;
  }

  int gcdValue = 1;
  for (int i = 0; i < xList.length; ++i) {
    double xVal = double.parse(xList[i]);
    double nVal = double.parse(nList[i]);

    int xi = xVal.round();
    int ni = nVal.round();

    int currentGcd = gcd(xi, ni);

    if (currentGcd > gcdValue) {
      gcdValue = currentGcd;
    }
  }

  if (gcdValue == 0) return false;

  double resultX = 0.0;
  double resultN = 0.0;

  for (int i = 0; i < xList.length; ++i) {
    double xVal = double.parse(xList[i]);
    double nVal = double.parse(nList[i]);

    int xi = xVal.round();
    int ni = nVal.round();

    resultX += xi / gcdValue.toDouble();
    resultN += ni / gcdValue.toDouble();
  }

  if (resultX.isNaN || resultN.isNaN) return false;

  if (resultX.abs() + resultN.abs() - max(resultX.abs(), resultN.abs()) < 1e-9) {
    return false;
  }

  return !allPositive;
}

