  bool leadingZerosAllowed = true; 

  for (int i = 0; i < maxLen; ++i) {
    int digitX = i < lenX ? int.parse(x[i]) : 0;
    int digitN = i < lenN ? int.parse(n[i]) : 0;

    if (digitX != digitN && !leadingZerosAllowed) {
      return false;
    } else if (digitX != digitN) {
      leadingZerosAllowed = false;
    }
  }

